import type { PrinterSettings } from './domain/profile.ts'

export interface SlicerMetadata {
  /** e.g. "OrcaSlicer 2.3.1", from the "generated by" header. */
  slicer: string | null
  /** Slicer total print time estimate, seconds. */
  estimatedSeconds: number | null
  /** Orca/Bambu "model printing time" (without prepare moves), seconds. */
  modelSeconds: number | null
  /** Comment the estimate came from, for display. */
  estimateSource: string | null
  /** `; key = value` pairs from the slicer config block. */
  config: Record<string, string>
  /** Printed model names in first-seen order, without file extension or copy suffixes. */
  objects: string[]
}

const CONFIG_LINE = /^;\s*([a-z][a-z0-9_]*)\s*=\s*(.*)$/
const GENERATED_BY = /^;\s*generated (?:by|with)\s+(.+?)(?:\s+on\s+\d.*)?$/i
const NORMAL_MODE_ESTIMATE = /^;\s*estimated printing time \(normal mode\)\s*=\s*(.+)$/i
const TOTAL_ESTIMATE = /total estimated time:\s*([^;]+)/i
const MODEL_TIME = /model printing time:\s*([^;]+)/i
const CURA_TIME = /^;\s*(?:PRINT\.)?TIME:\s*(\d+(?:\.\d+)?)\s*$/i
const PRINTING_OBJECT = /^;\s*printing object\s+(.+?)(?:\s+id:\s*\d+.*)?$/i
const CURA_MESH = /^;MESH:(.+)$/
const OBJECT_NAME = /\bNAME=(?:"([^"]+)"|(\S+))/i
const MAX_OBJECTS = 64

/** "Atlast PS5 Controller Stand.stl_id_0_copy_0" → "Atlast PS5 Controller Stand". */
export function cleanObjectName(raw: string): string {
  return raw
    .replace(/_id_\d+_copy_\d+$/i, '')
    .replace(/\.(stl|3mf|obj|step|stp|amf)$/i, '')
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Parses "1d 2h 3m 4s" / "1h 33m" / "45s" into seconds. */
export function parseDurationText(text: string): number | null {
  const pattern = /(\d+(?:\.\d+)?)\s*([dhms])/gi
  const factors: Record<string, number> = { d: 86400, h: 3600, m: 60, s: 1 }
  let seconds = 0
  let matched = false
  let match: RegExpExecArray | null

  while ((match = pattern.exec(text)) !== null) {
    seconds += Number(match[1]) * factors[match[2].toLowerCase()]
    matched = true
  }

  return matched ? seconds : null
}

export class SlicerMetadataCollector {
  private slicer: string | null = null
  private normalModeSeconds: number | null = null
  private totalSeconds: number | null = null
  private modelSeconds: number | null = null
  private curaSeconds: number | null = null
  private readonly config: Record<string, string> = {}
  private readonly objects = new Set<string>()

  private addObject(raw: string): void {
    if (this.objects.size >= MAX_OBJECTS) return
    const name = cleanObjectName(raw)
    if (name && name !== 'NONMESH') this.objects.add(name)
  }

  /** Klipper `EXCLUDE_OBJECT_DEFINE NAME=...` command. */
  pushObjectDefinition(command: string): void {
    const match = OBJECT_NAME.exec(command)
    if (match) this.addObject(match[1] ?? match[2])
  }

  /** Accepts a trimmed comment line starting with ";". */
  push(comment: string): void {
    const printing = PRINTING_OBJECT.exec(comment) ?? CURA_MESH.exec(comment)
    if (printing) {
      this.addObject(printing[1])
      return
    }

    const configMatch = CONFIG_LINE.exec(comment)
    if (configMatch) {
      this.config[configMatch[1]] = configMatch[2].trim()
      return
    }

    if (this.slicer === null) {
      const generated = GENERATED_BY.exec(comment)
      if (generated) {
        this.slicer = generated[1].trim()
        return
      }
    }

    const normalMode = NORMAL_MODE_ESTIMATE.exec(comment)
    if (normalMode) {
      this.normalModeSeconds = parseDurationText(normalMode[1])
      return
    }

    const total = TOTAL_ESTIMATE.exec(comment)
    if (total) this.totalSeconds = parseDurationText(total[1])
    const model = MODEL_TIME.exec(comment)
    if (model) this.modelSeconds = parseDurationText(model[1])
    if (total || model) return

    const cura = CURA_TIME.exec(comment)
    if (cura) this.curaSeconds = Number(cura[1])
  }

  peekConfig(key: string): string | undefined {
    return this.config[key]
  }

  finish(): SlicerMetadata {
    const candidates: Array<[number | null, string]> = [
      [this.totalSeconds, 'total estimated time'],
      [this.normalModeSeconds, 'estimated printing time (normal mode)'],
      [this.curaSeconds, ';TIME'],
    ]
    const [estimatedSeconds, estimateSource] = candidates.find(
      ([seconds]) => seconds !== null && seconds > 0,
    ) ?? [null, null]

    return {
      slicer: this.slicer,
      estimatedSeconds,
      modelSeconds: this.modelSeconds,
      estimateSource,
      config: { ...this.config },
      objects: [...this.objects],
    }
  }
}

export function firstPositiveNumber(value: string | undefined): number | null {
  if (value === undefined) return null
  const first = value.split(/[,;]/)[0].trim()
  if (!first || first.endsWith('%')) return null
  const number = Number(first)
  return Number.isFinite(number) && number > 0 ? number : null
}

/** Like firstPositiveNumber, but 0 is a real value (`slow_down_layer_time = 0`). */
export function firstNonNegativeNumber(value: string | undefined): number | null {
  if (value === undefined) return null
  const first = value.split(/[,;]/)[0].trim()
  if (!first || first.endsWith('%')) return null
  const number = Number(first)
  return Number.isFinite(number) && number >= 0 ? number : null
}

const ROLE_SPEED_KEYS: Record<string, string[]> = {
  'outer wall': ['outer_wall_speed', 'external_perimeter_speed'],
  'external perimeter': ['outer_wall_speed', 'external_perimeter_speed'],
  'wall-outer': ['outer_wall_speed', 'external_perimeter_speed'],
  'inner wall': ['inner_wall_speed', 'perimeter_speed'],
  perimeter: ['inner_wall_speed', 'perimeter_speed'],
  'wall-inner': ['inner_wall_speed', 'perimeter_speed'],
  'overhang wall': ['overhang_speed', 'overhang_1_4_speed'],
  'overhang perimeter': ['overhang_speed', 'overhang_1_4_speed'],
  'sparse infill': ['sparse_infill_speed', 'infill_speed'],
  'internal infill': ['sparse_infill_speed', 'infill_speed'],
  fill: ['sparse_infill_speed', 'infill_speed'],
  'internal solid infill': ['internal_solid_infill_speed', 'solid_infill_speed'],
  'solid infill': ['internal_solid_infill_speed', 'solid_infill_speed'],
  'top surface': ['top_surface_speed', 'top_solid_infill_speed'],
  'top solid infill': ['top_surface_speed', 'top_solid_infill_speed'],
  'bottom surface': ['initial_layer_speed', 'bottom_surface_speed'],
  skin: ['top_surface_speed', 'solid_infill_speed'],
  bridge: ['bridge_speed'],
  'bridge infill': ['bridge_speed'],
  'internal bridge': ['internal_bridge_speed', 'bridge_speed'],
  'gap infill': ['gap_infill_speed'],
  'gap fill': ['gap_infill_speed'],
  support: ['support_speed'],
  'support material': ['support_speed'],
  'support interface': ['support_interface_speed'],
  'support material interface': ['support_interface_speed'],
  'support transition': ['support_speed'],
  skirt: ['initial_layer_speed', 'outer_wall_speed'],
  brim: ['brim_speed', 'initial_layer_speed'],
  'skirt/brim': ['initial_layer_speed'],
  ironing: ['ironing_speed'],
}

/** Config print speed for a slicer `;TYPE:` / `; FEATURE:` role, mm/s. */
export function roleTargetSpeed(role: string, config: Record<string, string>): number | null {
  const keys = ROLE_SPEED_KEYS[role.trim().toLowerCase()]
  if (!keys) return null
  for (const key of keys) {
    const value = firstPositiveNumber(config[key])
    if (value !== null) return value
  }
  return null
}

/**
 * Slicer minimum layer time from the config block. 0 means “do not slow layers”.
 * Orca: `slow_down_layer_time`; PrusaSlicer: `slowdown_below_layer_time`.
 */
export function slicerMinimumLayerTime(config: Record<string, string>): number | null {
  for (const key of ['slow_down_layer_time', 'slowdown_below_layer_time']) {
    const value = firstNonNegativeNumber(config[key])
    if (value !== null) return value
  }
  return null
}

/** Floor speed when stretching a layer to the minimum time, mm/s. */
export function slicerSlowDownMinSpeed(config: Record<string, string>): number | null {
  for (const key of ['slow_down_min_speed', 'min_print_speed']) {
    const value = firstPositiveNumber(config[key])
    if (value !== null) return value
  }
  return null
}

export interface AppliedSlicerSetting {
  field: keyof PrinterSettings
  key: string
  value: number
}

/**
 * Fills audit limits from the slicer config block. Minimum layer time is set to 0:
 * slicers already slowed the emitted F for layer cooling, so extra pauses would
 * count that slowdown twice.
 */
export function settingsFromSlicerMetadata(
  metadata: SlicerMetadata,
  fallback: PrinterSettings,
  emittedReferenceAcceleration: number | null = null,
): { settings: PrinterSettings; applied: AppliedSlicerSetting[] } {
  const settings = { ...fallback }
  const applied: AppliedSlicerSetting[] = []
  const sources: Array<[keyof PrinterSettings, string[]]> = [
    ['maxVolumetricFlow', ['filament_max_volumetric_speed', 'max_volumetric_speed']],
    ['acceleration', ['default_acceleration']],
    ['maxPrintSpeed', ['machine_max_speed_x']],
    ['filamentDiameter', ['filament_diameter']],
  ]

  for (const [field, keys] of sources) {
    for (const key of keys) {
      const value = firstPositiveNumber(metadata.config[key])
      if (value === null) continue
      settings[field] = value
      applied.push({ field, key, value })
      break
    }
  }

  const fromSlicer = Boolean(metadata.slicer) || applied.length > 0

  if (
    emittedReferenceAcceleration &&
    !applied.some((item) => item.field === 'acceleration')
  ) {
    settings.acceleration = emittedReferenceAcceleration
    applied.push({
      field: 'acceleration',
      key: 'M204 / SET_VELOCITY_LIMIT',
      value: emittedReferenceAcceleration,
    })
  }

  if (fromSlicer) {
    settings.minimumLayerTime = 0
    applied.push({
      field: 'minimumLayerTime',
      key: 'slicer_slowdown_in_f',
      value: 0,
    })
  }

  return { settings, applied }
}

export type SlicerAgreement = 'match' | 'close' | 'off'

export interface SlicerComparison {
  slicer: string
  slicerSeconds: number
  oursSeconds: number
  /** (ours − slicer) / slicer × 100. Positive: Bottleneck3D is slower. */
  deltaPercent: number
  agreement: SlicerAgreement
}

/** ±5% match, ±15% close (TimeCheck expectation), otherwise off. */
export function compareWithSlicer(
  oursSeconds: number,
  metadata: SlicerMetadata,
): SlicerComparison | null {
  if (!metadata.estimatedSeconds) return null
  const deltaPercent =
    ((oursSeconds - metadata.estimatedSeconds) / metadata.estimatedSeconds) * 100
  const spread = Math.abs(deltaPercent)

  return {
    slicer: metadata.slicer ?? '',
    slicerSeconds: metadata.estimatedSeconds,
    oursSeconds,
    deltaPercent,
    agreement: spread <= 5 ? 'match' : spread <= 15 ? 'close' : 'off',
  }
}
